insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('flame-lily','ZWE','Flame Lily','Kajongwe — after jongwe, the cockerel (Shona)','flora',-17.8833,31.1333,'Zimbabwe’s national flower: a climbing lily whose swept-back petals flicker from gold to scarlet like a flame.','Specially protected under the Parks and Wildlife Act — wild flame lilies may not be picked or sold without a permit. It grows in woodland and on granite kopjes nationwide; this pin is a representative point near Harare.','Status','Specially protected',false,true,13,'{"color":"#E8432E","intensity":0.9,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://inaturalist-open-data.s3.amazonaws.com/photos/109637518/large.jpg","credit":"iNaturalist observer (no rights reserved)","license":"CC0","source":"https://www.inaturalist.org/observations/67801135"},{"url":"https://inaturalist-open-data.s3.amazonaws.com/photos/460665074/large.jpg","credit":"i_c_riddell","license":"CC BY","source":"https://www.inaturalist.org/observations/256875059"},{"url":"https://inaturalist-open-data.s3.amazonaws.com/photos/183085807/large.jpeg","credit":"Tony Rebelo","license":"CC BY-SA","source":"https://www.inaturalist.org/observations/108711306"}]}'::jsonb,'Gloriosa superba','["https://www.thenationalnews.com/world/africa/zimbabwe-s-national-flower-faces-extinction-1.497350/","https://www.gbif.org/species/2740024","https://en.wikipedia.org/wiki/Gloriosa_superba"]'::jsonb)
