insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lake-kariba','ZWE','Lake Kariba',null,'lake',-16.6,28.7,'A vast reservoir on the Zambezi, shared with Zambia: drowned forests, islands and hippo-lined shores stretching to the horizon.','Filled between 1958 and 1963 behind the 128 m Kariba Dam, it is the world’s largest man-made reservoir by volume. Its creation displaced about 57,000 Tonga people, and Operation Noah rescued around 6,000 large animals from the rising water.','Volume','~180 km³',false,true,16,'{"color":"#2EC4B6","intensity":0.85,"motion":"ripple"}'::jsonb,'{"video":"media/kariba-ed-mundondo.webm","fallback":"media/kariba-ed-mundondo.mp4","credit":"Edward Mundondo","license":"© Edward Mundondo","images":[{"url":"media/kariba-ed-mundondo-poster.jpg","credit":"Edward Mundondo","license":"© Edward Mundondo","source":null}],"note":"Original footage by Edward Mundondo: the lake from Kariba Heights, hippos on the shore, and the shoreline by boat."}'::jsonb,null,'["https://en.wikipedia.org/wiki/Lake_Kariba","https://en.wikipedia.org/wiki/Kariba_Dam","https://www.wikidata.org/wiki/Q1047206"]'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media, scientific_name=excluded.scientific_name, citations=excluded.citations;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('okavango-delta','BWA','Okavango Delta',null,'wetland',-19.3,22.9,'A river that never reaches the sea: the Okavango fans out across the Kalahari into a vast inland delta, flooding at the height of the dry season.','Inscribed in 2014 as the 1,000th World Heritage Site. Its flood comes down from the Angolan highlands months after the rains, drawing one of Africa’s great concentrations of wildlife into the desert.','Flood peak','~June–August',true,true,1,'{"color":"#3FA34D","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/Vista_a%C3%A9rea_del_delta_del_Okavango,_Botsuana,_2018-08-01,_DD_25.jpg/1280px-Vista_a%C3%A9rea_del_delta_del_Okavango,_Botsuana,_2018-08-01,_DD_25.jpg","credit":"Diego Delso","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Vista_a%C3%A9rea_del_delta_del_Okavango,_Botsuana,_2018-08-01,_DD_25.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Mokoros_in_the_Okavango_Delta_-_Botswana_-_panoramio.jpg/1280px-Mokoros_in_the_Okavango_Delta_-_Botswana_-_panoramio.jpg","credit":"diego_cue","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Mokoros_in_the_Okavango_Delta_-_Botswana_-_panoramio.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/The_Okavango_Delta_from_1,200_ft.jpg/1280px-The_Okavango_Delta_from_1,200_ft.jpg","credit":"Andrew Balet","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:The_Okavango_Delta_from_1,200_ft.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1432/","https://en.wikipedia.org/wiki/Okavango_Delta","https://www.wikidata.org/wiki/Q650872"]'::jsonb)
