insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('nxai-pan','BWA','Nxai Pan & Baines’ Baobabs',null,'savanna',-20.04,24.77,'A fossil lake bed of short grass and acacia islands, home to the baobab grove the artist Thomas Baines painted in 1862.','Part of the Makgadikgadi system; in the rains zebra and springbok gather on its grasslands, many arriving from the Chobe–Linyanti wetlands.','Baines painted it','1862',false,true,5,'{"color":"#E3B04B","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/de/Baines_Baobabs,_Nxai_Pan_(48591835096).jpg/1280px-Baines_Baobabs,_Nxai_Pan_(48591835096).jpg","credit":"Fabio Achilli from Milano, Italy","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Baines_Baobabs,_Nxai_Pan_(48591835096).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c6/Baines_Baobabs,_Nxai_Pan_(48591909117).jpg/1280px-Baines_Baobabs,_Nxai_Pan_(48591909117).jpg","credit":"Fabio Achilli from Milano, Italy","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Baines_Baobabs,_Nxai_Pan_(48591909117).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Nxai_Pan_National_Park","https://www.wikidata.org/wiki/Q859377"]'::jsonb)
