insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kubu-island','BWA','Kubu Island','Lekhubu (Setswana) · Ga’nnyo','rock',-20.893,25.819,'A granite ridge crowned with ancient baobabs, marooned in the white of Sowa Pan.','A sacred site and national monument: stone walls and Stone Age tools show people have gathered on this “island” in the salt for thousands of years.','Setting','Sowa Pan',false,true,6,'{"color":"#F2A65A","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/23/Kubu_Island_In_The_Salt_Flats_(190899107).jpeg/1280px-Kubu_Island_In_The_Salt_Flats_(190899107).jpeg","credit":"Rad Dougall","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Kubu_Island_In_The_Salt_Flats_(190899107).jpeg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/Baobabs_on_Kubu_island,_Botswana.jpg/1280px-Baobabs_on_Kubu_island,_Botswana.jpg","credit":"abi.bhattachan","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Baobabs_on_Kubu_island,_Botswana.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/d/d3/Boababs_at_Kubu.jpg","credit":"Hein waschefort","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Boababs_at_Kubu.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Kubu_Island","https://www.wikidata.org/w/index.php?search=Kubu+Island"]'::jsonb)
