insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('gcwihaba-caves','BWA','Gcwihaba Caves','Drotsky’s Cave','cave',-20.024,21.354,'A dolomite cave in the dry north-west Kalahari, hung with stalactites and home to bat colonies.','Its formations grew when the Kalahari was far wetter, so the cave is an archive of the region’s past climate.','Also called','Drotsky’s Cave',false,true,8,'{"color":"#7B6D8D","intensity":0.85,"motion":"sink"}'::jsonb,'{"note":"No openly licensed footage or photos found yet — swarm only."}'::jsonb,null,'["https://en.wikipedia.org/wiki/Gcwihaba","https://www.wikidata.org/wiki/Q29905437"]'::jsonb)
