insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('plains-zebra-botswana','BWA','Plains Zebra',null,'fauna',-19.9,25.3,'Botswana’s national animal: zebras support the national coat of arms, and the flag’s black-and-white band echoes their stripes.','Each year zebras trek between the Chobe–Linyanti wetlands and Nxai Pan, a round trip of about 500 km that is often cited as Africa’s longest recorded land-mammal migration.','Migration','~500 km round trip',false,true,10,'{"color":"#F4EFE3","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://inaturalist-open-data.s3.amazonaws.com/photos/214576160/large.jpeg","credit":"iNaturalist observer (no rights reserved)","license":"CC0","source":"https://www.inaturalist.org/observations/126462480"},{"url":"https://inaturalist-open-data.s3.amazonaws.com/photos/301070256/large.jpeg","credit":"Tony Eales","license":"CC BY-SA 4.0","source":"https://www.inaturalist.org/observations/173368539"},{"url":"https://inaturalist-open-data.s3.amazonaws.com/photos/12221796/large.jpeg","credit":"iNaturalist observer (no rights reserved)","license":"CC0","source":"https://www.inaturalist.org/observations/9054134"}]}'::jsonb,'Equus quagga','["https://www.gbif.org/species/2440892","https://en.wikipedia.org/wiki/Plains_zebra","https://en.wikipedia.org/wiki/Coat_of_arms_of_Botswana"]'::jsonb)
