insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('table-mountain','ZAF','Table Mountain','Hoerikwaggo: “mountain in the sea” (Khoekhoe)','mountain',-33.957,18.403,'Cape Town’s flat-topped sandstone mountain, often draped in a “tablecloth” of cloud pouring off its summit.','Part of the Cape Floral Region World Heritage Site and one of the New 7 Wonders of Nature. Its slopes hold an exceptional density of fynbos species.','Highest point','~1,085 m',false,true,2,'{"color":"#1F6F9F","intensity":0.85,"motion":"mist"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/0/03/Table_Mountain_Aerial_Cable_Car_01.webm/Table_Mountain_Aerial_Cable_Car_01.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/0/03/Table_Mountain_Aerial_Cable_Car_01.webm/Table_Mountain_Aerial_Cable_Car_01.webm.360p.mpeg4.mov","credit":"Spasimir Pilev","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Table_Mountain_Aerial_Cable_Car_01.webm"}'::jsonb,null,'["https://en.wikipedia.org/wiki/Table_Mountain","https://www.wikidata.org/wiki/Q213360","https://whc.unesco.org/en/list/1007/"]'::jsonb)
