insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('robben-island','ZAF','Robben Island',null,'heritage',-33.806,18.366,'A low island in Table Bay used for nearly four centuries as a place of banishment, imprisonment and isolation.','Nelson Mandela spent 18 of his 27 prison years here. World Heritage Site since 1999, as a symbol of the triumph of the human spirit over oppression.','Inscribed','1999',true,true,3,'{"color":"#F2E2C4","intensity":0.85,"motion":"orbit"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/8/8b/Table_Bay,_Trip_to_Robben_Island_by_Ferry.webm/Table_Bay,_Trip_to_Robben_Island_by_Ferry.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/8/8b/Table_Bay,_Trip_to_Robben_Island_by_Ferry.webm/Table_Bay,_Trip_to_Robben_Island_by_Ferry.webm.360p.mpeg4.mov","credit":"Nahid Sultan","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Table_Bay,_Trip_to_Robben_Island_by_Ferry.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/AHI_Treasures_of_Southern_Africa_3-07_0104_N_(554672987).jpg/1280px-AHI_Treasures_of_Southern_Africa_3-07_0104_N_(554672987).jpg","credit":"Joe Ross from Lansing, Michigan","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:AHI_Treasures_of_Southern_Africa_3-07_0104_N_(554672987).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/AHI_Treasures_of_Southern_Africa_3-07_0120_N_(554674637).jpg/1280px-AHI_Treasures_of_Southern_Africa_3-07_0120_N_(554674637).jpg","credit":"Joe Ross from Lansing, Michigan","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:AHI_Treasures_of_Southern_Africa_3-07_0120_N_(554674637).jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/916/","https://en.wikipedia.org/wiki/Robben_Island","https://www.wikidata.org/wiki/Q192493"]'::jsonb)
