insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('cradle-of-humankind','ZAF','Cradle of Humankind',null,'heritage',-26.016,27.734,'Limestone caves north-west of Johannesburg that have yielded a large share of the world’s early hominin fossils.','Home of “Mrs Ples” and “Little Foot” at Sterkfontein and Homo naledi at Rising Star. Part of the Fossil Hominid Sites World Heritage Site (1999, extended in 2005 to Taung and Makapan).','Oldest finds','~3.6 million years',true,true,5,'{"color":"#B5835A","intensity":0.85,"motion":"sink"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Cradle_of_Humankind_at_from_Maropeng_Visitor_Centre.jpg/1280px-Cradle_of_Humankind_at_from_Maropeng_Visitor_Centre.jpg","credit":"Olof Somell (Nobel Museum)","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Cradle_of_Humankind_at_from_Maropeng_Visitor_Centre.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cc/Sterkfontein_Caves_23.jpg/1280px-Sterkfontein_Caves_23.jpg","credit":"Mike Peel (www.mikepeel.net)","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Sterkfontein_Caves_23.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/53/Sterkfontein_Caves_59.jpg/1280px-Sterkfontein_Caves_59.jpg","credit":"Mike Peel (www.mikepeel.net)","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Sterkfontein_Caves_59.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/915/","https://en.wikipedia.org/wiki/Cradle_of_Humankind","https://www.wikidata.org/wiki/Q1130112"]'::jsonb)
