insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('richtersveld','ZAF','Richtersveld Cultural and Botanical Landscape',null,'heritage',-28.6,17.2,'A rugged mountain desert where Nama herders still move with the seasons, carrying portable rush-mat houses.','World Heritage Site since 2007 for a semi-nomadic pastoral way of life that is centuries old, set among one of the richest succulent floras on Earth.','Inscribed','2007',true,true,6,'{"color":"#C97B3C","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Nama_huts.JPG/1280px-Nama_huts.JPG","credit":"Newydd (Wikimedia Commons)","license":"CC BY 2.5","source":"https://commons.wikimedia.org/wiki/File:Nama_huts.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2d/Cheiridopsis_denticulata-PICT2507.jpg/1280px-Cheiridopsis_denticulata-PICT2507.jpg","credit":"Winfried Bruenken (Amrum)","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:Cheiridopsis_denticulata-PICT2507.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/PICT2453_Ornithogalum_suaveolen.JPG/1280px-PICT2453_Ornithogalum_suaveolen.JPG","credit":"Winfried Bruenken (Amrum)","license":"CC BY-SA 2.5","source":"https://commons.wikimedia.org/wiki/File:PICT2453_Ornithogalum_suaveolen.JPG"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1265/","https://en.wikipedia.org/wiki/Richtersveld","https://www.wikidata.org/wiki/Q1353565"]'::jsonb)
