insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('cape-floral-region','ZAF','Cape Floral Region',null,'landform',-32.35,19.08,'The smallest and richest of the world’s six floral kingdoms, packed into the mountains of the south-western Cape.','Less than 0.5% of Africa’s area, yet nearly 20% of its flora, and about 69% of its ~9,000 plant species grow nowhere else. 13 protected clusters; this pin marks the Cederberg.','Endemic plants','~69%',true,true,7,'{"color":"#E05A7A","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/77/Cederberg,_South_Africa_(32644366536).jpg/1280px-Cederberg,_South_Africa_(32644366536).jpg","credit":"yeowatzup from Göttingen, Germany","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Cederberg,_South_Africa_(32644366536).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fb/Cederberg,_South_Africa_-_Sunset1.jpg/1280px-Cederberg,_South_Africa_-_Sunset1.jpg","credit":"Domenico Convertini","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Cederberg,_South_Africa_-_Sunset1.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Cederberg,_South_Africa_2023_2.jpg/1280px-Cederberg,_South_Africa_2023_2.jpg","credit":"dconvertini","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Cederberg,_South_Africa_2023_2.jpg"}],"note":"Photos from the Cederberg cluster of the property."}'::jsonb,null,'["https://whc.unesco.org/en/list/1007/","https://en.wikipedia.org/wiki/Cape_Floristic_Region"]'::jsonb)
