insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('isimangaliso','ZAF','iSimangaliso Wetland Park','iSimangaliso: “miracle and wonder” (isiZulu)','wetland',-27.65,32.57,'About 280 km of coast, coral reefs, forested dunes, lakes and swamps on the KwaZulu-Natal coast.','World Heritage Site since 1999. In 2025 it was extended across the border to include Mozambique’s Maputo National Park, forming one transboundary site.','Coastline','~280 km',true,true,9,'{"color":"#2EC4B6","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/Mission_Rocks_%22Beach%22_(46635539581).jpg/1280px-Mission_Rocks_%22Beach%22_(46635539581).jpg","credit":"Bernard DUPONT from FRANCE","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Mission_Rocks_%22Beach%22_(46635539581).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2d/ISimangaliso_Wetland_Park,_gravel_road.jpg/1280px-ISimangaliso_Wetland_Park,_gravel_road.jpg","credit":"Ossewa","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:ISimangaliso_Wetland_Park,_gravel_road.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Observation_deck_at_iSimangaliso_Wetland_Park.jpg/1280px-Observation_deck_at_iSimangaliso_Wetland_Park.jpg","credit":"Ossewa","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Observation_deck_at_iSimangaliso_Wetland_Park.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/914/","https://en.wikipedia.org/wiki/ISimangaliso_Wetland_Park","https://www.wikidata.org/wiki/Q310719"]'::jsonb)
