insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('augrabies-falls','ZAF','Augrabies Falls','Aukoerebis: “place of great noise” (Khoekhoe)','waterfall',-28.59,20.34,'The Orange River thunders into a granite gorge in the middle of the Northern Cape desert.','The main fall drops about 56 m into a gorge roughly 18 km long, protected by Augrabies Falls National Park since 1966.','Main drop','~56 m',false,true,10,'{"color":"#7BDFF2","intensity":0.85,"motion":"cascade"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/c/c6/Augrabies_Falls_Video-001.ogv/Augrabies_Falls_Video-001.ogv.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/c/c6/Augrabies_Falls_Video-001.ogv/Augrabies_Falls_Video-001.ogv.360p.mpeg4.mov","credit":"NJR ZA","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Augrabies_Falls_Video-001.ogv","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Augrabies_Falls_1.JPG/1280px-Augrabies_Falls_1.JPG","credit":"Octagon","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Augrabies_Falls_1.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Augrabies_-_Twin_Falls_-_001.jpg/1280px-Augrabies_-_Twin_Falls_-_001.jpg","credit":"NJR ZA","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Augrabies_-_Twin_Falls_-_001.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Augrabies_Falls","https://www.wikidata.org/wiki/Q39544"]'::jsonb)
