insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('blyde-river-canyon','ZAF','Blyde River Canyon','Motlatse Canyon','gorge',-24.58,30.8,'A 26 km sandstone canyon on the Drakensberg escarpment, with the Three Rondavels standing over the Blyde River.','Often called one of the largest “green canyons” on Earth for its subtropical forest. At Bourke’s Luck the Treur and Blyde rivers have scoured giant potholes.','Length','~26 km',false,true,11,'{"color":"#3E8E41","intensity":0.85,"motion":"zigzag"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/0/01/Motlatse_Canyon_Bourke_Luck_Potholes_(2).webm/Motlatse_Canyon_Bourke_Luck_Potholes_(2).webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/0/01/Motlatse_Canyon_Bourke_Luck_Potholes_(2).webm/Motlatse_Canyon_Bourke_Luck_Potholes_(2).webm.360p.mpeg4.mov","credit":"Pierre André","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Motlatse_Canyon_Bourke_Luck_Potholes_(2).webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Blyde_River_Canyon_with_3_Rondavels_panorama.jpeg/1280px-Blyde_River_Canyon_with_3_Rondavels_panorama.jpeg","credit":"Hansm","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Blyde_River_Canyon_with_3_Rondavels_panorama.jpeg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Blyde_River_Canyon_Panorama_2013.jpg/1280px-Blyde_River_Canyon_Panorama_2013.jpg","credit":"Stefan Schäfer, Lich","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Blyde_River_Canyon_Panorama_2013.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Blyde_River_Canyon","https://www.wikidata.org/wiki/Q886892"]'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media, scientific_name=excluded.scientific_name, citations=excluded.citations;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mapungubwe','ZAF','Mapungubwe Cultural Landscape',null,'heritage',-22.19,29.24,'A sandstone hill above the Limpopo–Shashe confluence, seat of the first known kingdom in Southern Africa.','Between about 1220 and 1290 it grew rich on gold and ivory traded to the Indian Ocean; the famous golden rhino came from a royal grave here. Its decline preceded the rise of Great Zimbabwe. World Heritage Site since 2003.','Capital','c. 1220–1290',true,true,12,'{"color":"#D4A373","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/53/Mapungubwe_hill_limpopo.jpg/1280px-Mapungubwe_hill_limpopo.jpg","credit":"Marius Loots","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Mapungubwe_hill_limpopo.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Mapungubwe_Cultural_Landscape-114907.jpg/1280px-Mapungubwe_Cultural_Landscape-114907.jpg","credit":"Francesco Bandarin","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Mapungubwe_Cultural_Landscape-114907.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a8/Mapungubwe_Cultural_Landscape-114909.jpg/1280px-Mapungubwe_Cultural_Landscape-114909.jpg","credit":"Francesco Bandarin","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:Mapungubwe_Cultural_Landscape-114909.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1099/","https://en.wikipedia.org/wiki/Kingdom_of_Mapungubwe","https://www.wikidata.org/wiki/Q1136251"]'::jsonb)
  on conflict (slug) do update set country_iso=excluded.country_iso, name=excluded.name, local_name=excluded.local_name, category=excluded.category, lat=excluded.lat, lng=excluded.lng, summary=excluded.summary, uniqueness=excluded.uniqueness, stat_label=excluded.stat_label, stat_value=excluded.stat_value, unesco=excluded.unesco, visible=excluded.visible, sort_order=excluded.sort_order, art=excluded.art, media=excluded.media, scientific_name=excluded.scientific_name, citations=excluded.citations;
insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('barberton-makhonjwa','ZAF','Barberton Makhonjwa Mountains',null,'mountain',-25.974,31.014,'Some of the oldest and best-preserved volcanic and sedimentary rocks on Earth, 3.6–3.25 billion years old.','They preserve debris from meteorite impacts and some of the earliest traces of life, a window onto the young Earth. World Heritage Site since 2018.','Rock age','3.6–3.25 bn years',true,true,13,'{"color":"#6D597A","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/Barberton_oli_202169_lrg.jpg/1280px-Barberton_oli_202169_lrg.jpg","credit":"NASA Earth Observatory","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Barberton_oli_202169_lrg.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/The_Crocodile_River_traverses_South_Africa_ESA418736,_Makhonjwa.jpg/1280px-The_Crocodile_River_traverses_South_Africa_ESA418736,_Makhonjwa.jpg","credit":"European Space Agency","license":"CC BY-SA 3.0 IGO","source":"https://commons.wikimedia.org/wiki/File:The_Crocodile_River_traverses_South_Africa_ESA418736,_Makhonjwa.jpg"}],"note":"Satellite views (NASA Landsat 8, ESA Sentinel-2)."}'::jsonb,null,'["https://whc.unesco.org/en/list/1575/","https://en.wikipedia.org/wiki/Makhonjwa_Mountains"]'::jsonb)
