insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('khomani-cultural-landscape','ZAF','ǂKhomani Cultural Landscape',null,'heritage',-25.69,20.37,'Red Kalahari dunes on the Botswana and Namibia borders, home to the ǂKhomani San and their traditions.','Inscribed in 2017 for a San way of life, and a knowledge of the desert, that run from the Stone Age to the present.','Inscribed','2017',true,true,14,'{"color":"#D9480F","intensity":0.85,"motion":"orbit"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/b/bc/Cheetah_(Acinonyx_jubatus)_juvenile_....webm/Cheetah_(Acinonyx_jubatus)_juvenile_....webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/b/bc/Cheetah_(Acinonyx_jubatus)_juvenile_....webm/Cheetah_(Acinonyx_jubatus)_juvenile_....webm.360p.mpeg4.mov","credit":"Bernard DUPONT","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Cheetah_(Acinonyx_jubatus)_juvenile_....webm","note":"Filmed in the Nossob riverbed, Kgalagadi Transfrontier Park, which the cultural landscape lies within."}'::jsonb,null,'["https://whc.unesco.org/en/list/1545/","https://en.wikipedia.org/wiki/%C7%82Khomani_Cultural_Landscape"]'::jsonb)
