insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kruger-national-park','ZAF','Kruger National Park',null,'savanna',-24,31.5,'One of Africa’s great game reserves, stretching about 360 km along the Mozambique border.','First protected as the Sabi Game Reserve in 1898, it is now part of the Great Limpopo Transfrontier Park with Mozambique and Zimbabwe.','Area','~19,600 km²',false,true,17,'{"color":"#D9A441","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/6/61/Plains_Zebra_(Equus_quagga_burchellii)_coming_to_drink_....webm/Plains_Zebra_(Equus_quagga_burchellii)_coming_to_drink_....webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/6/61/Plains_Zebra_(Equus_quagga_burchellii)_coming_to_drink_....webm/Plains_Zebra_(Equus_quagga_burchellii)_coming_to_drink_....webm.360p.mpeg4.mov","credit":"Bernard DUPONT","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Plains_Zebra_(Equus_quagga_burchellii)_coming_to_drink_....webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Kruger_National_Park,_Hazyview,_South_Africa_(Unsplash).jpg/1280px-Kruger_National_Park,_Hazyview,_South_Africa_(Unsplash).jpg","credit":"AnnaKate Auten","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Kruger_National_Park,_Hazyview,_South_Africa_(Unsplash).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Kruger_National_Park_(5386947728).jpg/1280px-Kruger_National_Park_(5386947728).jpg","credit":"David Siu from Memphis, TN","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Kruger_National_Park_(5386947728).jpg"}],"note":"Plains zebra coming to drink, H1-3 road south of Satara."}'::jsonb,null,'["https://en.wikipedia.org/wiki/Kruger_National_Park"]'::jsonb)
