insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('king-protea','ZAF','King Protea',null,'flora',-33.98,18.98,'South Africa’s national flower, with the largest flower head of any protea: up to about 30 cm across.','A fire-adapted fynbos shrub that resprouts from a thick underground stem after veld fires. The pin is a representative point from GBIF records in the Western Cape.','Flower head','up to ~30 cm',false,true,18,'{"color":"#E05A7A","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Protea_cynaroides_154805716.jpg/1280px-Protea_cynaroides_154805716.jpg","credit":"Tony Rebelo","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Protea_cynaroides_154805716.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Protea_cynaroides_MS_9113.jpg/1280px-Protea_cynaroides_MS_9113.jpg","credit":"Marco Schmidt","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Protea_cynaroides_MS_9113.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Prot%C3%A9a_royale_%C3%A0_Stellenbosch_(Afrique_du_Sud).jpg/1280px-Prot%C3%A9a_royale_%C3%A0_Stellenbosch_(Afrique_du_Sud).jpg","credit":"Pierre André","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Prot%C3%A9a_royale_%C3%A0_Stellenbosch_(Afrique_du_Sud).jpg"}]}'::jsonb,'Protea cynaroides','["https://en.wikipedia.org/wiki/Protea_cynaroides","https://www.gbif.org/species/search?q=Protea%20cynaroides"]'::jsonb)
