insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('african-penguin','ZAF','African Penguin',null,'fauna',-34.373,18.893,'Africa’s only penguin, braying like a donkey on the granite of the Cape coast.','Classified as Critically Endangered by the IUCN in 2024 after decades of steep decline. Colonies such as Stony Point at Betty’s Bay (this pin) are closely protected.','IUCN status','Critically Endangered',false,true,19,'{"color":"#1F6F9F","intensity":0.85,"motion":"ripple"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/26/African_penguins,_Betty''s_Bay_06.webm/African_penguins,_Betty''s_Bay_06.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/2/26/African_penguins,_Betty''s_Bay_06.webm/African_penguins,_Betty''s_Bay_06.webm.360p.mpeg4.mov","credit":"Spasimir Pilev","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:African_penguins,_Betty''s_Bay_06.webm","note":"Wild colony at Betty’s Bay."}'::jsonb,'Spheniscus demersus','["https://en.wikipedia.org/wiki/African_penguin","https://www.iucnredlist.org/species/22697810/"]'::jsonb)
