insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('etosha','NAM','Etosha National Park','Etosha: “great white place” (Oshiwambo)','savanna',-18.8,16.3,'A salt pan white as chalk, ringed by waterholes where elephant, rhino and lion gather in the dry season.','Proclaimed a game reserve in 1907, it is one of Africa’s oldest protected areas. The pan alone covers about 4,800 km².','Pan','~4,800 km²',false,true,3,'{"color":"#EDE6D6","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/92/Etosha_pan_(1).jpg/1280px-Etosha_pan_(1).jpg","credit":"Ji-Elle","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Etosha_pan_(1).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Giraffa_Pan_Etosha.tif/lossy-page1-1280px-Giraffa_Pan_Etosha.tif.jpg","credit":"Buiobuione","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Giraffa_Pan_Etosha.tif"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Etosha_pan_-_namibia.jpg/1280px-Etosha_pan_-_namibia.jpg","credit":"Moongateclimber","license":"CC BY 3.0","source":"https://commons.wikimedia.org/wiki/File:Etosha_pan_-_namibia.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Etosha_National_Park","https://www.wikidata.org/wiki/Q675633"]'::jsonb)
