insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('epupa-falls','NAM','Epupa Falls',null,'waterfall',-17,13.25,'The Kunene River splinters into dozens of channels and tumbles through a series of falls on the Angola border.','The falls spread over about 1.5 km, framed by baobabs and makalani palms in the homeland of the Himba.','Spread','~1.5 km',false,true,5,'{"color":"#2EC4B6","intensity":0.85,"motion":"cascade"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/5/5c/Epupa_falls_&_Cunene_River.webm/Epupa_falls_&_Cunene_River.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/5/5c/Epupa_falls_&_Cunene_River.webm/Epupa_falls_&_Cunene_River.webm.360p.mpeg4.mov","credit":"Виктор Пинчук","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Epupa_falls_&_Cunene_River.webm","images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3a/Epupa_falls_(main_falls).jpg/1280px-Epupa_falls_(main_falls).jpg","credit":"Hans Hillewaert","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Epupa_falls_(main_falls).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/be/Epupa_Falls_chasm.jpg/1280px-Epupa_Falls_chasm.jpg","credit":"Hans Hillewaert","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Epupa_Falls_chasm.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Epupa_Falls","https://www.wikidata.org/wiki/Q187918"]'::jsonb)
