insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('brandberg','NAM','Brandberg','Dâures: “burning mountain” (Damara)','mountain',-21.15,14.58,'Namibia’s highest mountain, a granite massif that glows red at sunset.','Its summit, Königstein, reaches about 2,573 m, and its ravines hold thousands of rock paintings, including the famous “White Lady”.','Highest point','~2,573 m',false,true,6,'{"color":"#E76F51","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Brandberg_Mountain_Panorama.jpg/1280px-Brandberg_Mountain_Panorama.jpg","credit":"Joel Holdsworth","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Brandberg_Mountain_Panorama.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/Approach_to_Brandberg_White_Lady_site_(3690485342).jpg/1280px-Approach_to_Brandberg_White_Lady_site_(3690485342).jpg","credit":"Greg Willis from Denver, CO, USA","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Approach_to_Brandberg_White_Lady_site_(3690485342).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/50_(1_sur_1).JPG/1280px-50_(1_sur_1).JPG","credit":"Angliers","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:50_(1_sur_1).JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Brandberg_Mountain","https://www.wikidata.org/wiki/Q897834"]'::jsonb)
