insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('spitzkoppe','NAM','Spitzkoppe',null,'rock',-21.83,15.2,'Bald granite peaks more than 120 million years old, rising about 700 m out of the Namib plains: the “Matterhorn of Namibia”.','Rock arches and shelters at its base, such as Bushman’s Paradise, hold San paintings.','Summit','~1,728 m',false,true,7,'{"color":"#F2A65A","intensity":0.85,"motion":"orbit"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Approaching_Spitzkoppe_28.06.2008_08-05-57.jpg/1280px-Approaching_Spitzkoppe_28.06.2008_08-05-57.jpg","credit":"Hansueli Krapf","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Approaching_Spitzkoppe_28.06.2008_08-05-57.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/2008-06-28_08-17-43_Namibia_Erongo_Usakos.JPG/1280px-2008-06-28_08-17-43_Namibia_Erongo_Usakos.JPG","credit":"Hansueli Krapf","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:2008-06-28_08-17-43_Namibia_Erongo_Usakos.JPG"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a1/2008-06-28_08-37-23_Namibia_Erongo_Uigaran.JPG/1280px-2008-06-28_08-37-23_Namibia_Erongo_Uigaran.JPG","credit":"Hansueli Krapf","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:2008-06-28_08-37-23_Namibia_Erongo_Uigaran.JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Spitzkoppe","https://www.wikidata.org/wiki/Q2124779"]'::jsonb)
