insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('dragons-breath-cave','NAM','Dragon’s Breath Cave','Drachenhauchloch','cave',-19.468,17.786,'A cave hiding the world’s largest known non-subglacial underground lake.','Found in 1986, the lake covers almost 2 hectares of crystal-clear water, and the cave reaches a total depth of about 205 m. It is named for the warm, moist air that breathes out of its entrance.','Lake area','~2 ha',false,true,9,'{"color":"#1B3A5C","intensity":0.85,"motion":"sink"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/f/ff/Sketch_of_Dragons_Breath_Hole_1986.jpg","credit":"Des Fourie","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Sketch_of_Dragons_Breath_Hole_1986.jpg"}],"note":"A 1986 survey sketch of the cave; no open photo of the lake yet."}'::jsonb,null,'["https://en.wikipedia.org/wiki/Dragon%27s_Breath_Cave","https://www.wikidata.org/wiki/Q1254270"]'::jsonb)
