insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('gemsbok','NAM','Gemsbok',null,'fauna',-23.66,15.93,'A desert antelope with rapier-straight horns; a pair support Namibia’s coat of arms.','Built for drought, it can go long periods without drinking, getting water from melons and roots and letting its body heat rise by day to save water.','Symbol of','Namibia’s coat of arms',false,true,11,'{"color":"#EDE6D6","intensity":0.85,"motion":"herd"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/b/b0/Gemsboks_(Oryx_gazella)_coming_to_drink_with_Secretarybird_passing_by_.......webm/Gemsboks_(Oryx_gazella)_coming_to_drink_with_Secretarybird_passing_by_.......webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/b/b0/Gemsboks_(Oryx_gazella)_coming_to_drink_with_Secretarybird_passing_by_.......webm/Gemsboks_(Oryx_gazella)_coming_to_drink_with_Secretarybird_passing_by_.......webm.360p.mpeg4.mov","credit":"Bernard DUPONT","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Gemsboks_(Oryx_gazella)_coming_to_drink_with_Secretarybird_passing_by_.......webm","note":"Stand-in: filmed in the Kgalagadi (South Africa); no open Namibian clip yet."}'::jsonb,'Oryx gazella','["https://en.wikipedia.org/wiki/Gemsbok","https://en.wikipedia.org/wiki/Coat_of_arms_of_Namibia"]'::jsonb)
