insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lake-malawi-national-park','MWI','Lake Malawi National Park',null,'lake',-14.03,34.88,'Clear water and granite islands at the lake’s southern tip, alive with hundreds of cichlid species found nowhere else.','World Heritage Site since 1984, created mainly to protect fish. Its cichlids are a textbook case of evolution, often compared to Darwin’s finches. The lake is shared with Mozambique (Lago Niassa) and Tanzania.','Inscribed','1984',true,true,1,'{"color":"#1F78B4","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/Otter_Point,_Cape_Maclear_(Malawi).jpg/1280px-Otter_Point,_Cape_Maclear_(Malawi).jpg","credit":"Hans Hillewaert","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Otter_Point,_Cape_Maclear_(Malawi).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/Haliaeetus_vocifer_-Cape_Maclear,_Malawi_-fishing-8.jpg/1280px-Haliaeetus_vocifer_-Cape_Maclear,_Malawi_-fishing-8.jpg","credit":"Joachim Huber","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Haliaeetus_vocifer_-Cape_Maclear,_Malawi_-fishing-8.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/Morning_fish_guys_@_cape_maclear.jpg/1280px-Morning_fish_guys_@_cape_maclear.jpg","credit":"GAGAN P V","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Morning_fish_guys_@_cape_maclear.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/289/","https://en.wikipedia.org/wiki/Lake_Malawi_National_Park","https://www.wikidata.org/wiki/Q1077596"]'::jsonb)
