insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mount-mulanje','MWI','Mount Mulanje Cultural Landscape',null,'mountain',-15.912,35.658,'A granite massif rising abruptly from tea estates; its summit, Sapitwa, is the highest point in Malawi.','Inscribed in 2025 as a cultural landscape: the Yao, Mang’anja and Lhomwe hold the mountain sacred as home of deities, spirits and ancestors.','Sapitwa Peak','3,002 m',true,true,2,'{"color":"#4C9A2A","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/6/60/Mount_Mulanje.jpg","credit":"africankelli","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Mount_Mulanje.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Mount_Mulanje_Mozambique.jpg/1280px-Mount_Mulanje_Mozambique.jpg","credit":"mikeymckay","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Mount_Mulanje_Mozambique.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8a/Chambe.jpg/1280px-Chambe.jpg","credit":"Dr. Ferdinand Groeger","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Chambe.jpg"}]}'::jsonb,null,'["https://whc.unesco.org/en/list/1201/","https://en.wikipedia.org/wiki/Mulanje_Massif","https://www.wikidata.org/wiki/Q1510436"]'::jsonb)
