insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('nyika-plateau','MWI','Nyika Plateau',null,'mountain',-10.67,33.83,'A rolling grassland plateau above 2,000 m in Malawi’s largest national park.','In the rains its grasslands flower with around 200 orchid species, while roan antelope and zebra graze between patches of montane forest.','Area','~3,200 km²',false,true,4,'{"color":"#F2B134","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Nyika_dambo.jpg/1280px-Nyika_dambo.jpg","credit":"Dr. Thomas Wagner","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Nyika_dambo.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/53/Nyika_National_Park,_Malawi_(2489516573).jpg/1280px-Nyika_National_Park,_Malawi_(2489516573).jpg","credit":"Joachim Huber from Switzerland","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Nyika_National_Park,_Malawi_(2489516573).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Nyika_afromontane_forest.jpg/1280px-Nyika_afromontane_forest.jpg","credit":"Dr. Thomas Wagner","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Nyika_afromontane_forest.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Nyika_National_Park","https://www.wikidata.org/wiki/Q1567460"]'::jsonb)
