insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('zomba-plateau','MWI','Zomba Plateau',null,'mountain',-15.33,35.32,'A flat-topped massif above Malawi’s old colonial capital, cloaked in forest, streams and waterfalls.','At about 2,087 m, its viewpoints look out toward Lake Chilwa and Mulanje on clear days.','Highest point','~2,087 m',false,true,5,'{"color":"#2BB3C0","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Panorama_Blick_auf_das_Zomba_Plateau_vom_Ndangopuma_H%C3%BCgel.jpg/1280px-Panorama_Blick_auf_das_Zomba_Plateau_vom_Ndangopuma_H%C3%BCgel.jpg","credit":"Rockwurm","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Panorama_Blick_auf_das_Zomba_Plateau_vom_Ndangopuma_H%C3%BCgel.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Zomba_Plateau_seen_from_south.jpg/1280px-Zomba_Plateau_seen_from_south.jpg","credit":"Felefuchs","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Zomba_Plateau_seen_from_south.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/Mulunguzi_dam_and_Williams_Falls.jpg/1280px-Mulunguzi_dam_and_Williams_Falls.jpg","credit":"Felefuchs","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Mulunguzi_dam_and_Williams_Falls.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Zomba_Plateau","https://www.wikidata.org/wiki/Q8073720"]'::jsonb)
