insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('liwonde','MWI','Liwonde National Park',null,'river',-14.83,35.33,'The Shire River winds through palm savanna crowded with hippos and crocodiles.','Managed by African Parks since 2015, which has brought back cheetahs and lions.','Established','1973',false,true,6,'{"color":"#4C9A2A","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/d/db/Liwonde_Park_-_view_of_Shire_River.jpg","credit":"Brian Dell","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Liwonde_Park_-_view_of_Shire_River.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/3/3e/Liwonde-Park.jpg","credit":"Dr. Ferdinand Groeger","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Liwonde-Park.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/Liwonde_NP_-_panoramio.jpg/1280px-Liwonde_NP_-_panoramio.jpg","credit":"Timon Zingg","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Liwonde_NP_-_panoramio.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Liwonde_National_Park","https://www.wikidata.org/wiki/Q2739189"]'::jsonb)
