insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('lake-chilwa','MWI','Lake Chilwa',null,'wetland',-15.3,35.7,'A shallow, slightly salty lake ringed by swamps and floodplains near the Mozambique border.','A Ramsar wetland and UNESCO biosphere reserve. It has dried out completely several times and refilled, yet still supports a major fishery.','Size','~60 × 40 km',false,true,7,'{"color":"#2BB3C0","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Lakechilwa.jpg/1280px-Lakechilwa.jpg","credit":"Felefuchs","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Lakechilwa.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Punter_on_Lake_Chilwa,_Malawi.jpg/1280px-Punter_on_Lake_Chilwa,_Malawi.jpg","credit":"Wardtmar","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Punter_on_Lake_Chilwa,_Malawi.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Lake_Chilwa,_Malawi.jpg/1280px-Lake_Chilwa,_Malawi.jpg","credit":"U.S. Geological Survey","license":"CC0","source":"https://commons.wikimedia.org/wiki/File:Lake_Chilwa,_Malawi.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Lake_Chilwa","https://www.wikidata.org/wiki/Q746975"]'::jsonb)
