insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mulanje-cedar','MWI','Mulanje Cedar',null,'flora',-15.9,35.53,'Malawi’s national tree: a towering cypress found only on Mount Mulanje.','Critically Endangered after logging and fires, with a replanting effort under way on the massif. Trees can reach 40–50 m.','IUCN status','Critically Endangered',false,true,9,'{"color":"#3A7D44","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://inaturalist-open-data.s3.amazonaws.com/photos/432430723/large.jpeg","credit":"Tony Rebelo","license":"CC BY-SA 4.0","source":"https://www.inaturalist.org/observations/242567006"},{"url":"https://inaturalist-open-data.s3.amazonaws.com/photos/433063149/large.jpeg","credit":"Tony Rebelo","license":"CC BY-SA 4.0","source":"https://www.inaturalist.org/observations/242901522"},{"url":"https://upload.wikimedia.org/wikipedia/commons/9/92/Widdringtonia_whytei_Mulanje_Malawi.jpg","credit":"Amanita Phalloides (German Wikipedia)","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Widdringtonia_whytei_Mulanje_Malawi.jpg"}]}'::jsonb,'Widdringtonia whytei','["https://en.wikipedia.org/wiki/Widdringtonia_whytei","https://www.inaturalist.org/taxa/Widdringtonia-whytei"]'::jsonb)
