insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kafue','ZMB','Kafue National Park',null,'savanna',-15.3,25.9,'Zambia’s largest national park, about 22,400 km² of floodplain and miombo woodland.','In the north the Busanga Plains flood each year and draw red lechwe, puku and lions; it is one of the largest parks in Africa.','Area','~22,400 km²',false,true,2,'{"color":"#198754","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Kafue_National_Park.jpg/1280px-Kafue_National_Park.jpg","credit":"LittleT889","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Kafue_National_Park.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Safari_Road_Savanna_Kafue_Jul23_A7C_05580.jpg/1280px-Safari_Road_Savanna_Kafue_Jul23_A7C_05580.jpg","credit":"Timothy A. Gonsalves","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Safari_Road_Savanna_Kafue_Jul23_A7C_05580.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Area_Burn_Savanna_Kafue_Jul23_A7C_05607.jpg/1280px-Area_Burn_Savanna_Kafue_Jul23_A7C_05607.jpg","credit":"Timothy A. Gonsalves","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Area_Burn_Savanna_Kafue_Jul23_A7C_05607.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Kafue_National_Park","https://www.wikidata.org/wiki/Q1721097"]'::jsonb)
