insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('liuwa-plain','ZMB','Liuwa Plain National Park',null,'savanna',-14.5,22.48,'A vast floodplain grassland in Barotseland, with Africa’s second-largest wildebeest migration.','Protected since the 19th century, when the Litunga (king of the Lozi) made it a royal hunting ground. Hyenas, lions and wild dogs follow the herds.','Area','3,369 km²',false,true,5,'{"color":"#E9C46A","intensity":0.85,"motion":"herd"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/Liuwa_Plain_National_Park_01.jpg/1280px-Liuwa_Plain_National_Park_01.jpg","credit":"S1m0nB3rry","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Liuwa_Plain_National_Park_01.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Liuwa_Plain_National_Park_02.jpg/1280px-Liuwa_Plain_National_Park_02.jpg","credit":"S1m0nB3rry","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Liuwa_Plain_National_Park_02.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a1/Liuwa_Plain_National_Park_04.jpg/1280px-Liuwa_Plain_National_Park_04.jpg","credit":"S1m0nB3rry","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Liuwa_Plain_National_Park_04.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Liuwa_Plain_National_Park","https://www.wikidata.org/wiki/Q1471784"]'::jsonb)
