insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('ngonye-falls','ZMB','Ngonye Falls','Sioma Falls','waterfall',-16.65,23.57,'The Zambezi pours over a horseshoe of rock in western Zambia, a few hundred kilometres upstream of Victoria Falls.','A broad crescent of cascades in Sioma Ngwezi country, a quieter preview of the river that later becomes Mosi-oa-Tunya.','River','Zambezi',false,true,7,'{"color":"#7FC8F8","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Ngonye_falls_at_Zambezi_river,_Zambia.jpg/1280px-Ngonye_falls_at_Zambezi_river,_Zambia.jpg","credit":"Petrtyl","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Ngonye_falls_at_Zambezi_river,_Zambia.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/Ngonye_falls_at_Zambezi_river,_Zambia_(aerial_view).jpg/1280px-Ngonye_falls_at_Zambezi_river,_Zambia_(aerial_view).jpg","credit":"Petrtyl","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Ngonye_falls_at_Zambezi_river,_Zambia_(aerial_view).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/21/Zambezi_river_with_Ngonye_falls_in_Sioma_district,_Western_province,_Zambia.jpg/1280px-Zambezi_river_with_Ngonye_falls_in_Sioma_district,_Western_province,_Zambia.jpg","credit":"Petrtyl","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Zambezi_river_with_Ngonye_falls_in_Sioma_district,_Western_province,_Zambia.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Ngonye_Falls","https://www.wikidata.org/wiki/Q1650303"]'::jsonb)
