insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('kundalila-falls','ZMB','Kundalila Falls','Kundalila: “crying dove”','waterfall',-13.15,30.7,'A clear stream drops about 60 m off the Muchinga escarpment.','Rock pools at the top sit on the edge of the escarpment, with wide views over miombo woodland.','Drop','~60 m',false,true,9,'{"color":"#7BDFF2","intensity":0.85,"motion":"cascade"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Kundalila_Falls,_serenje_Zambia_01.jpg/1280px-Kundalila_Falls,_serenje_Zambia_01.jpg","credit":"Mr. Chishinzhi","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Kundalila_Falls,_serenje_Zambia_01.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/Kundalila_Falls_downside.jpg/1280px-Kundalila_Falls_downside.jpg","credit":"Sybryn","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Kundalila_Falls_downside.jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Kundalila_Falls","https://www.wikidata.org/wiki/Q6444278"]'::jsonb)
