insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('zambezi-teak','ZMB','Zambezi Teak','Mukusi','flora',-17.2,24.6,'A hardwood of the Kalahari sands that once formed dense forests across western Zambia.','Its heavy red timber went into railway sleepers and parquet floors across the region, and much of the old forest has been logged. The pin is a representative point near Sesheke.','Also called','Rhodesian / Zambian teak',false,true,10,'{"color":"#B87333","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://inaturalist-open-data.s3.amazonaws.com/photos/528743838/large.jpg","credit":"Timothy Whitehead","license":"CC BY 4.0","source":"https://www.inaturalist.org/observations/293786155"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Baikiaea_plurijuga_arbre_MHNT.JPG/1280px-Baikiaea_plurijuga_arbre_MHNT.JPG","credit":"Roger Culos","license":"CC BY-SA 3.0","source":"https://commons.wikimedia.org/wiki/File:Baikiaea_plurijuga_arbre_MHNT.JPG"}]}'::jsonb,'Baikiaea plurijuga','["https://en.wikipedia.org/wiki/Baikiaea_plurijuga","https://www.inaturalist.org/observations/293786155"]'::jsonb)
