insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('quirimbas','MOZ','Quirimbas Archipelago',null,'coast',-12.35,40.6,'A chain of coral islands and mangroves in Cabo Delgado, including Ibo’s old Swahili-Portuguese town.','The national park (2002) protects the southern islands and a large mainland area, and is also a UNESCO biosphere reserve.','Park founded','2002',false,true,4,'{"color":"#2EC4B6","intensity":0.85,"motion":"ripple"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/37/Ilha_do_Ibo_-_sunset-01.jpg/1280px-Ilha_do_Ibo_-_sunset-01.jpg","credit":"Rosino","license":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Ilha_do_Ibo_-_sunset-01.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Iss070e026322.jpg/1280px-Iss070e026322.jpg","credit":"NASA Johnson Space Center","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Iss070e026322.jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/Quirimbas_Fisherman_on_dhow_safari.JPG/1280px-Quirimbas_Fisherman_on_dhow_safari.JPG","credit":"Travel Local","license":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Quirimbas_Fisherman_on_dhow_safari.JPG"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Quirimbas_National_Park","https://www.wikidata.org/wiki/Q1546990"]'::jsonb)
