insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mount-mabu','MOZ','Mount Mabu','the “Google Forest”','forest',-16.3,36.4,'About 7,000 ha of old-growth rainforest on a remote mountain, spotted by scientists on Google Earth in 2005.','Expeditions from 2008 found species new to science, including butterflies, chameleons and a snake. It is one of the largest mid-altitude rainforests in southern Africa.','Forest','~7,000 ha',false,true,5,'{"color":"#2D6A4F","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3b/Mount_Mabu,_Mozambique_(ASTER).jpg/1280px-Mount_Mabu,_Mozambique_(ASTER).jpg","credit":"NASA/METI/AIST/Japan Space Systems, U.S./Japan ASTER Science Team","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Mount_Mabu,_Mozambique_(ASTER).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/1/19/Mount_Mabu_(10.3897-zse.92.9948)_Figure_2_(cropped).jpg","credit":"Conradie W et al. (ZooKeys)","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Mount_Mabu_(10.3897-zse.92.9948)_Figure_2_(cropped).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Mount_Mabu","https://www.wikidata.org/wiki/Q1613668"]'::jsonb)
