insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('mount-namuli','MOZ','Mount Namuli',null,'mountain',-15.37,37.03,'A granite dome rising to 2,419 m: Mozambique’s second-highest mountain and a “sky island” of endemic life.','Its montane grassland and forest patches shelter species found nowhere else, such as the Namuli apalis and Vincent’s bush squirrel.','Height','2,419 m',false,true,6,'{"color":"#6A994E","intensity":0.85,"motion":"mist"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/4/4c/Mount_Namuli_(10.3897-zse.92.9948)_Figure_2_(cropped).jpg","credit":"Conradie W et al. (ZooKeys)","license":"CC BY 4.0","source":"https://commons.wikimedia.org/wiki/File:Mount_Namuli_(10.3897-zse.92.9948)_Figure_2_(cropped).jpg"}]}'::jsonb,null,'["https://en.wikipedia.org/wiki/Mount_Namuli","https://www.wikidata.org/wiki/Q1516857"]'::jsonb)
