insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('african-blackwood','MOZ','African Blackwood','Pau-preto (Portuguese) · mpingo (Swahili)','flora',-17.33,34.39,'A small, slow-growing tree with near-black heartwood: the wood of clarinets, oboes and bagpipes.','Much of the world’s supply comes from Mozambique and Tanzania. Trees take 60 years or more to mature, and the species is rated Near Threatened. The pin is a representative point from GBIF records.','Matures in','60+ years',false,true,8,'{"color":"#3B2F2F","intensity":0.85,"motion":"bloom"}'::jsonb,'{"images":[{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/Dalbergia_melanoxylon_(tree).jpg/1280px-Dalbergia_melanoxylon_(tree).jpg","credit":"Marie-Elisabeth Gorge","license":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Dalbergia_melanoxylon_(tree).jpg"},{"url":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/Dalbergia_melanoxylon_1DS-II_4-5854.jpg/1280px-Dalbergia_melanoxylon_1DS-II_4-5854.jpg","credit":"SAplants","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Dalbergia_melanoxylon_1DS-II_4-5854.jpg"}],"note":"Stand-ins: a tree in Tanzania and flowers in Pretoria NBG."}'::jsonb,'Dalbergia melanoxylon','["https://en.wikipedia.org/wiki/Dalbergia_melanoxylon","https://www.gbif.org/species/search?q=Dalbergia%20melanoxylon"]'::jsonb)
