insert into public.wonders (slug,country_iso,name,local_name,category,lat,lng,summary,uniqueness,stat_label,stat_value,unesco,visible,sort_order,art,media,scientific_name,citations) values ('dugong-bazaruto','MOZ','Dugong',null,'fauna',-21.95,35.35,'A gentle sea cow grazing the seagrass in the bay behind the Bazaruto islands.','About 120 animals here form the largest remnant dugong population in Mozambique, often described as the last viable one on East Africa’s coast.','Population','~120',false,true,9,'{"color":"#5FA8D3","intensity":0.85,"motion":"ripple"}'::jsonb,'{"video":"https://upload.wikimedia.org/wikipedia/commons/transcoded/f/fa/Dugong_dugon._Seekuh._%D0%94%D1%8E%D0%B3%D0%BE%D0%BD%D1%8C.Rotes_Meer..DSCF9602.webm/Dugong_dugon._Seekuh._%D0%94%D1%8E%D0%B3%D0%BE%D0%BD%D1%8C.Rotes_Meer..DSCF9602.webm.480p.vp9.webm","fallback":"https://upload.wikimedia.org/wikipedia/commons/transcoded/f/fa/Dugong_dugon._Seekuh._%D0%94%D1%8E%D0%B3%D0%BE%D0%BD%D1%8C.Rotes_Meer..DSCF9602.webm/Dugong_dugon._Seekuh._%D0%94%D1%8E%D0%B3%D0%BE%D0%BD%D1%8C.Rotes_Meer..DSCF9602.webm.360p.mpeg4.mov","credit":"Kora27","license":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Dugong_dugon._Seekuh._%D0%94%D1%8E%D0%B3%D0%BE%D0%BD%D1%8C.Rotes_Meer..DSCF9602.webm","note":"Stand-in: filmed in the Red Sea (Egypt); no open Bazaruto footage yet."}'::jsonb,'Dugong dugon','["https://en.wikipedia.org/wiki/Bazaruto_Archipelago","https://en.wikipedia.org/wiki/Dugong"]'::jsonb)
